1	/**
2	 * CategoryService
3	 *
4	 * Service for managing family expense categories
5	 * Specification: #{#exp3a} - Family Category Management
6	 * Authority: developer
7	 * Priority: High
8	 *
9	 * Key Principles:
10	 * - Categories are scoped to families (family_id), not individual users
11	 * - All active family members can view and use the same categories
12	 * - New families receive default categories on creation
13	 * - Category names must be unique per family (case-insensitive)
14	 * - Categories support optional color coding
15	 */
16	
17	import type { SupabaseClient } from '@supabase/supabase-js';
18	import type { Category } from '$lib/types/Category';
19	import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';
20	
21	/**
22	 * Category data structure — single source of truth lives in $lib/types/Category.
23	 * Re-exported here so existing `import type { Category } from './CategoryService'`
24	 * consumers keep working.
25	 */
26	export type { Category } from '$lib/types/Category';
27	
28	/**
29	 * Default category definition
30	 */
31	interface DefaultCategory {
32		name: string;
33		color: string;
34	}
35	
36	/**
37	 * Fields that updateCategory writes to a category row.
38	 * `color` is only included when the caller explicitly provides one.
39	 */
40	interface CategoryUpdateData {
41		name: string;
42		updated_at: string;
43		color?: string | null;
44	}
45	
46	/**
47	 * Default categories for new families
48	 * Specification: #{#exp3a} Requirement 3
49	 *
50	 * Updated with user's custom category list
51	 * Families can replace, delete, or ignore these categories as needed
52	 */
