102	/**
103	 * CategoryService Class
104	 * Handles all category-related operations
105	 */
106	export class CategoryService {
107		private supabase: SupabaseClient;
108	
109		constructor(supabase: SupabaseClient) {
110			this.supabase = supabase;
111		}
112	
113		/**
114		 * Get list of default categories
115		 * Specification: #{#exp3a} Requirement 3
116		 */
117		getDefaultCategoryList(): DefaultCategory[] {
118			return DEFAULT_CATEGORIES;
119		}
120	
121		/**
122		 * Get all categories for a family
123		 *
124		 * @param familyId - Family ID to filter categories
125		 * @returns Array of categories ordered by name
126		 *
127		 * Specification: #{#exp3a} Requirement 1
128		 */
129		async getFamilyCategories(familyId: string): Promise<Category[]> {
130			// Requirement: Family ID validation
131			if (!familyId) {
132				throw new Error('Family ID is required');
133			}
134	
135			// Query categories filtered by family_id
136			// RLS policies ensure user is an active member of this family
137			const { data, error } = await this.supabase
138				.from('categories')
139				.select('*')
140				.eq('family_id', familyId)
141				.order('name', { ascending: true });
142	
143			if (error) {
144				throw new Error(error.message);
145			}
146	
147			return data || [];
148		}
149	
150		/**
151		 * DEPRECATED: Use getFamilyCategories instead
152		 * @deprecated This method is maintained for backward compatibility
153		 */
154		async getUserCategories(userId: string): Promise<Category[]> {
155			console.warn('getUserCategories is deprecated. Use getFamilyCategories instead.');
156	
157			// Get user's default family and fetch categories for that family
158			const { data: familyMember, error: fmError } = await this.supabase
159				.from('family_members')
160				.select('family_id')
161				.eq('user_id', userId)
162				.eq('is_default', true)
163				.eq('status', 'active')
164				.single();
165	
166			if (fmError || !familyMember) {
167				throw new Error('Could not find default family for user');
168			}
169	
170			return this.getFamilyCategories(familyMember.family_id);
171		}
172	
173		/**
174		 * Get the spending-hierarchy Areas of Importance for a family, ordered by
175		 * sort_order (the report's top-tier order).
176		 */
177		async getFamilyImportanceAreas(familyId: string): Promise<ImportanceArea[]> {
178			if (!familyId) {
179				throw new Error('Family ID is required');
180			}
181	
182			const { data, error } = await this.supabase
183				.from('importance_areas')
184				.select('*')
185				.eq('family_id', familyId)
186				.order('sort_order', { ascending: true });
187	
188			if (error) {
189				throw new Error(error.message);
190			}
191	
192			return data || [];
193		}
194	
195		/**
196		 * Get the spending-hierarchy Groupings for a family. Each group carries its
197		 * `importance_area_id`.
198		 */
199		async getFamilyGroups(familyId: string): Promise<CategoryGroup[]> {
200			if (!familyId) {
201				throw new Error('Family ID is required');
202			}
203	
204			const { data, error } = await this.supabase
205				.from('category_groups')
206				.select('*')
207				.eq('family_id', familyId)
208				.order('name', { ascending: true });
209	
210			if (error) {
211				throw new Error(error.message);
212			}
213	
214			return data || [];
215		}
216	
217		/**
218		 * Seed the default spending hierarchy (Importance areas + Groupings, and map
219		 * the default categories into them) for a family. Idempotent server-side —
220		 * safe to call whenever a family has no hierarchy yet. Mirrors the
221		 * lazy-initialization pattern used for default categories.
222		 */
223		async createDefaultHierarchy(familyId: string): Promise<void> {
224			if (!familyId) {
225				throw new Error('Family ID is required');
226			}
227	
228			const { error } = await this.supabase.rpc('create_default_hierarchy', {
229				p_family_id: familyId
230			});
231	
232			if (error) {
233				throw new Error(error.message);
234			}
235		}
236	
237		/**
238		 * Assign a Category to a Grouping (or clear it back to Uncategorized).
239		 *
240		 * The spending-hierarchy editor's core mutation: a category with no
241		 * `group_id` falls into the report's Uncategorized bucket, so this is how a
242		 * custom or renamed category gets pulled into a real Grouping without SQL.
243		 * Pass `null` to unassign.
244		 */
245		async assignCategoryToGroup(categoryId: string, groupId: string | null): Promise<void> {
246			if (!categoryId) {
247				throw new Error('Category ID is required');
248			}
249	
250			const { error } = await this.supabase
251				.from('categories')
252				.update({ group_id: groupId, updated_at: new Date().toISOString() })
253				.eq('id', categoryId);
254	
255			if (error) {
256				throw new Error(error.message);
257			}
258		}
259	
260		/**
261		 * Move a Grouping to a different Area of Importance.
262		 *
263		 * Importance attaches to the Grouping (not the category), so re-parenting a
264		 * Grouping re-buckets all of its categories in the report at once.
265		 */
266		async moveGroupToImportance(groupId: string, importanceAreaId: string): Promise<void> {
267			if (!groupId) {
268				throw new Error('Group ID is required');
269			}
270			if (!importanceAreaId) {
271				throw new Error('Importance area ID is required');
272			}
273	
274			const { error } = await this.supabase
275				.from('category_groups')
276				.update({ importance_area_id: importanceAreaId, updated_at: new Date().toISOString() })
277				.eq('id', groupId);
278	
279			if (error) {
280				throw new Error(error.message);
281			}
282		}
283	
284		/**
285		 * Create a new Grouping under an Area of Importance.
286		 *
287		 * The one hierarchy tier the seed can't anticipate: a family needing a Grouping
288		 * beyond the 13 defaults adds it here (the editor's "Add a Grouping" form), then
289		 * assigns categories into it. Importance attaches to the Grouping, so the area
290		 * is chosen at creation. Deleting Groupings isn't offered — an empty Grouping is
291		 * harmless, since the report suppresses zero-activity rows.
292		 */
293		async createGroup(
294			familyId: string,
295			name: string,
296			importanceAreaId: string
297		): Promise<CategoryGroup> {
298			if (!familyId) {
299				throw new Error('Family ID is required');
300			}
301			if (!name || name.trim() === '') {
302				throw new Error('Grouping name is required');
303			}
304			if (name.length > 100) {
305				throw new Error('Grouping name must be 100 characters or less');
306			}
307			if (!importanceAreaId) {
308				throw new Error('Importance area ID is required');
309			}
310	
311			const { data, error } = await this.supabase
312				.from('category_groups')
313				.insert({
314					family_id: familyId,
315					name: name.trim(),
316					importance_area_id: importanceAreaId
317				})
318				.select()
319				.single();
320	
321			if (error) {
322				if (error.code === '23505') {
323					throw new Error('A grouping with this name already exists in this family');
324				}
325				throw new Error(error.message);
326			}
327	
328			return data;
329		}
330	
331		/**
332		 * Rename a Grouping.
333		 *
334		 * The report and editor key off the Grouping id, not its name, so a rename just
335		 * relabels it everywhere — no re-linking of categories or importance needed.
336		 */
337		async renameGroup(groupId: string, name: string): Promise<void> {
338			if (!groupId) {
339				throw new Error('Group ID is required');
340			}
341			if (!name || name.trim() === '') {
342				throw new Error('Grouping name is required');
343			}
344			if (name.length > 100) {
345				throw new Error('Grouping name must be 100 characters or less');
346			}
347	
348			const { error } = await this.supabase
349				.from('category_groups')
350				.update({ name: name.trim(), updated_at: new Date().toISOString() })
351				.eq('id', groupId);
352	
353			if (error) {
354				if (error.code === '23505') {
355					throw new Error('A grouping with this name already exists in this family');
356				}
357				throw new Error(error.message);
358			}
359		}
360	
361		/**
362		 * Create default categories for a new family
363		 *
364		 * @param familyId - Family ID to create categories for
365		 *
366		 * Specification: #{#exp3a} Requirements 2 & 3
367		 */
368		async createDefaultCategories(familyId: string): Promise<void> {
369			if (!familyId) {
370				throw new Error('Family ID is required');
371			}
372	
373			// Only create if family has no categories
374			const existing = await this.getFamilyCategories(familyId);
375			if (existing.length > 0) {
376				return; // Family already has categories
377			}
378	
379			// Insert default categories directly using the DEFAULT_CATEGORIES constant
380			// This ensures we always use the latest category list
381			const categoriesToInsert = DEFAULT_CATEGORIES.map((cat) => ({
382				family_id: familyId,
383				name: cat.name,
384				color: cat.color
385			}));
386	
387			const { error } = await this.supabase.from('categories').insert(categoriesToInsert);
388	
389			// Ignore unique constraint violations (23505) - categories already exist
390			if (error && error.code !== '23505') {
391				throw new Error(error.message);
392			}
393		}
394	
395		/**
396		 * Create a new custom category
397		 *
398		 * @param familyId - Family ID
399		 * @param name - Category name
400		 * @param color - Optional hex color code (#RRGGBB)
401		 * @param groupId - Optional Grouping to file the new category under (spending
402		 *   hierarchy). Omit/null leaves it Uncategorized.
403		 * @returns Created category
404		 *
405		 * Specification: #{#exp3a} Requirements 4, 7, 8
406		 */
407		async createCategory(
408			familyId: string,
409			name: string,
410			color?: string,
411			groupId?: string | null
412		): Promise<Category> {
413			// Validation
414			if (!familyId) {
415				throw new Error('Family ID is required');
416			}
417	
418			if (!name || name.trim() === '') {
419				throw new Error('Category name is required');
420			}
421	
422			if (name.length > 100) {
423				throw new Error('Category name must be 100 characters or less');
424			}
425	
426			// Validate color format if provided
427			if (color !== undefined && color !== null && color !== '') {
428				if (!this.isValidHexColor(color)) {
429					throw new Error('Invalid color format. Use hex format: #RRGGBB');
430				}
431			}
432	
433			// Insert category. group_id is only set when a Grouping was chosen, so an
434			// unassigned new category stays Uncategorized (group_id NULL).
435			const { data, error } = await this.supabase
436				.from('categories')
437				.insert({
438					family_id: familyId,
439					name: name.trim(),
440					color: color || null,
441					group_id: groupId || null
442				})
443				.select()
444				.single();
445	
446			if (error) {
447				// Handle unique constraint violation
448				if (error.code === '23505') {
449					throw new Error('A category with this name already exists in this family');
450				}
451				throw new Error(error.message);
452			}
453	
454			return data;
455		}
456	
457		/**
458		 * Update an existing category
459		 *
460		 * @param categoryId - Category ID to update
461		 * @param name - New category name
462		 * @param color - New color (optional)
463		 * @returns Updated category
464		 *
465		 * Specification: #{#exp3a} Requirement 5
466		 */
467		async updateCategory(categoryId: string, name: string, color?: string): Promise<Category> {
468			if (!categoryId) {
469				throw new Error('Category ID is required');
470			}
471	
472			if (!name || name.trim() === '') {
473				throw new Error('Category name is required');
474			}
475	
476			if (name.length > 100) {
477				throw new Error('Category name must be 100 characters or less');
478			}
479	
480			// Validate color format if provided
481			if (color !== undefined && color !== null && color !== '') {
482				if (!this.isValidHexColor(color)) {
483					throw new Error('Invalid color format. Use hex format: #RRGGBB');
484				}
485			}
486	
487			const updateData: CategoryUpdateData = {
488				name: name.trim(),
489				updated_at: new Date().toISOString()
490			};
491	
492			if (color !== undefined) {
493				updateData.color = color;
494			}
495	
496			const { data, error } = await this.supabase
497				.from('categories')
498				.update(updateData)
499				.eq('id', categoryId)
500				.select()
501				.single();
502	
503			if (error) {
504				// Handle unique constraint violation
505				if (error.code === '23505') {
506					throw new Error('A category with this name already exists in this family');
507				}
508				throw new Error(error.message);
509			}
510	
511			return data;
512		}
513	
514		/**
515		 * Delete a category
516		 *
517		 * @param categoryId - Category ID to delete
518		 *
519		 * Specification: #{#exp3a} Requirement 6
520		 */
521		async deleteCategory(categoryId: string): Promise<void> {
522			if (!categoryId) {
523				throw new Error('Category ID is required');
524			}
525	
526			const { error } = await this.supabase.from('categories').delete().eq('id', categoryId);
527	
528			if (error) {
529				throw new Error(error.message);
530			}
531		}
532	
533		/**
534		 * Check if a category has associated expenses
535		 *
536		 * @param categoryId - Category ID to check
537		 * @returns True if category has expenses, false otherwise
538		 *
539		 * Specification: #{#exp3a} Requirement 6
540		 */
541		async categoryHasExpenses(categoryId: string): Promise<boolean> {
542			if (!categoryId) {
543				throw new Error('Category ID is required');
544			}
545	
546			const { data, error } = await this.supabase
547				.from('expense_categories')
548				.select('receipt_id')
549				.eq('category_id', categoryId);
550	
551			if (error) {
552				throw new Error(error.message);
553			}
554	
555			return data && data.length > 0;
556		}
557	
558		/**
559		 * Validate hex color format
560		 *
561		 * @param color - Color string to validate
562		 * @returns True if valid hex color
563		 *
564		 * Specification: #{#exp3a} Requirement 8
565		 */
566		private isValidHexColor(color: string): boolean {
567			const hexColorRegex = /^#[0-9A-Fa-f]{6}$/;
568			return hexColorRegex.test(color);
569		}
570	}
