1	/**
2	 * hierarchyTree — shape the flat spending-hierarchy tables into the nested tree
3	 * the hierarchy editor renders.
4	 *
5	 * Input is the three family-scoped tables loaded separately (Areas of Importance,
6	 * Groupings, Categories). Output is Importance → Grouping → Category nested for
7	 * display, plus a flat `unassigned` bucket of categories with no `group_id`
8	 * (the ones that fall to "Uncategorized" in the report and are the whole reason
9	 * the editor exists).
10	 *
11	 * Pure and unit-tested, in the style of buildSpendingReport — the editor page
12	 * only loads data, renders this tree, and calls the mutation service.
13	 *
14	 * Ordering mirrors the report: Importance by `sort_order`, Groupings alphabetical
15	 * within an Importance, Categories alphabetical within a Grouping (and in the
16	 * unassigned bucket). Unlike the report, zero-activity rows are NOT suppressed —
17	 * the editor must show every Grouping and Category so they can be (re)assigned.
18	 *
19	 * Design: docs/plans/2026-07-09-spending-report-design.md
20	 */
21	
22	import type { Category } from '$lib/types/Category';
23	import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';
24	
25	export interface HierarchyGroupNode {
26		group: CategoryGroup;
27		categories: Category[];
28	}
29	
30	export interface HierarchyImportanceNode {
31		importance: ImportanceArea;
32		groups: HierarchyGroupNode[];
33	}
34	
35	export interface HierarchyTree {
36		importances: HierarchyImportanceNode[];
37		/** Categories with no `group_id` — the editor's "assign me" bucket. */
38		unassigned: Category[];
39	}
40	
41	const byName = (a: { name: string }, b: { name: string }): number => a.name.localeCompare(b.name);
42	
43	/**
44	 * Build the nested Importance → Grouping → Category tree plus the unassigned
45	 * bucket. Groupings whose `importance_area_id` doesn't resolve to a known
46	 * Importance are treated as orphaned and folded into a synthetic trailing
47	 * Importance so their categories are still reachable in the editor (defensive —
48	 * the FK should prevent this, but the editor must never silently drop a group).
49	 */
50	export function buildHierarchyTree(
51		importanceAreas: ImportanceArea[],
52		groups: CategoryGroup[],
53		categories: Category[]
54	): HierarchyTree {
55		// Categories bucketed by their group_id (null → unassigned).
56		const categoriesByGroup = new Map<string, Category[]>();
57		const unassigned: Category[] = [];
58		for (const category of categories) {
59			if (!category.group_id) {
60				unassigned.push(category);
61				continue;
62			}
63			const bucket = categoriesByGroup.get(category.group_id);
64			if (bucket) {
65				bucket.push(category);
66			} else {
67				categoriesByGroup.set(category.group_id, [category]);
68			}
69		}
70	
71		const groupNode = (group: CategoryGroup): HierarchyGroupNode => ({
72			group,
73			categories: (categoriesByGroup.get(group.id) ?? []).slice().sort(byName)
74		});
75	
76		const knownImportanceIds = new Set(importanceAreas.map((area) => area.id));
77		const groupsByImportance = new Map<string, CategoryGroup[]>();
78		const orphanGroups: CategoryGroup[] = [];
79		for (const group of groups) {
80			if (!knownImportanceIds.has(group.importance_area_id)) {
81				orphanGroups.push(group);
82				continue;
83			}
84			const bucket = groupsByImportance.get(group.importance_area_id);
85			if (bucket) {
86				bucket.push(group);
87			} else {
88				groupsByImportance.set(group.importance_area_id, [group]);
89			}
90		}
91	
92		const importances: HierarchyImportanceNode[] = importanceAreas
93			.slice()
94			.sort((a, b) => a.sort_order - b.sort_order)
95			.map((importance) => ({
96				importance,
97				groups: (groupsByImportance.get(importance.id) ?? []).slice().sort(byName).map(groupNode)
98			}));
99	
100		if (orphanGroups.length > 0) {
101			importances.push({
102				importance: { id: '', name: 'Unassigned Importance', sort_order: Number.MAX_SAFE_INTEGER },
103				groups: orphanGroups.slice().sort(byName).map(groupNode)
104			});
105		}
106	
