1	<script lang="ts">
2		/**
3		 * Spending hierarchy editor
4		 *
5		 * Lets the family maintainer restructure the spending hierarchy without SQL:
6		 *   - assign a Category to a Grouping (or back to Uncategorized)
7		 *   - move a Grouping to a different Area of Importance
8		 *   - add a new Grouping under an Area of Importance
9		 *   - rename a Grouping
10		 *
11		 * The report attaches Importance to the Grouping, so moving a Grouping
12		 * re-buckets all its Categories at once. Categories with no Grouping land in
13		 * the "Unassigned" bucket up top — the whole reason this editor exists (the
14		 * seed maps categories by name, so custom/renamed ones start unassigned).
15		 *
16		 * Tree shaping is the pure `buildHierarchyTree`; this page loads the three
17		 * hierarchy tables, renders the tree, and calls CategoryService mutations,
18		 * reloading after each. Design: docs/plans/2026-07-09-spending-report-design.md
19		 */
20	
21		import { onMount } from 'svelte';
22		import { resolve } from '$app/paths';
23		import { supabase } from '$lib/supabaseClient';
24		import { CategoryService } from '$lib/services/CategoryService';
25		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
26		import { buildHierarchyTree, type HierarchyTree } from '$lib/utils/hierarchyTree';
27		import HierarchyEditor from '$lib/components/HierarchyEditor.svelte';
28		import type { ImportanceArea } from '$lib/types/Hierarchy';
29		import type { Session } from '@supabase/supabase-js';
30	
31		let session: Session | null = $state(null);
32		let familyId: string | null = $state(null);
33		let loading = $state(true);
34		let saving = $state(false);
35		let error: string | null = $state(null);
36		let tree = $state<HierarchyTree | null>(null);
37		let importanceAreas = $state<ImportanceArea[]>([]);
38	
39		const service = new CategoryService(supabase);
40	
41		onMount(async () => {
42			const { data } = await supabase.auth.getSession();
43			session = data.session;
44			if (!session) {
45				loading = false;
46				return;
47			}
48	
49			familyId = await getDefaultFamilyId();
50			if (!familyId) {
51				error = 'No family found. Please contact support.';
52				loading = false;
53				return;
54			}
55	
56			await load();
57		});
58	
59		async function load() {
60			if (!familyId) return;
61	
62			try {
63				loading = true;
64				error = null;
65	
66				// Self-seed the default hierarchy if this family has none yet (mirrors
67				// the /spending report's lazy-init), so the editor is never empty.
68				let areas = await service.getFamilyImportanceAreas(familyId);
69				if (areas.length === 0) {
70					await service.createDefaultHierarchy(familyId);
71					areas = await service.getFamilyImportanceAreas(familyId);
72				}
73	
74				const [groups, categories] = await Promise.all([
75					service.getFamilyGroups(familyId),
76					service.getFamilyCategories(familyId)
77				]);
78	
79				importanceAreas = areas;
80				tree = buildHierarchyTree(areas, groups, categories);
81			} catch (err) {
82				console.error('Error loading hierarchy:', err);
83				error = err instanceof Error ? err.message : 'Failed to load the hierarchy';
84			} finally {
85				loading = false;
86			}
87		}
88	
89		/** Run a mutation, surface any error in the UI, then reload the tree. */
90		async function mutate(action: () => Promise<void>) {
91			try {
92				saving = true;
93				error = null;
94				await action();
95				await load();
96			} catch (err) {
97				console.error('Error saving hierarchy change:', err);
98				error = err instanceof Error ? err.message : 'Failed to save the change';
99			} finally {
100				saving = false;
101			}
102		}
103	
104		function assignCategory(categoryId: string, groupId: string | null) {
105			mutate(() => service.assignCategoryToGroup(categoryId, groupId));
106		}
107	
108		function moveGroup(groupId: string, importanceAreaId: string) {
109			if (!importanceAreaId) return;
110			mutate(() => service.moveGroupToImportance(groupId, importanceAreaId));
111		}
112	
113		function createGroup(name: string, importanceAreaId: string) {
114			const fid = familyId;
115			if (!fid || !name.trim() || !importanceAreaId) return;
116			mutate(async () => {
117				await service.createGroup(fid, name, importanceAreaId);
118			});
119		}
120	
121		function renameGroup(groupId: string, name: string) {
122			if (!name.trim()) return;
123			mutate(() => service.renameGroup(groupId, name));
124		}
125	
126		const hasHierarchy = $derived(tree !== null && tree.importances.length > 0);
127	</script>
