3		 * HierarchyEditor — presentational tree for the spending-hierarchy editor.
4		 *
5		 * Pure: props in, callbacks out. It renders the Importance → Grouping →
6		 * Category tree (plus the "Unassigned categories" bucket) and emits
7		 * `onAssignCategory` / `onMoveGroup` when a select changes. The page owns data
8		 * loading and the CategoryService mutations; this component owns none of that,
9		 * so it renders under the vitest-browser harness without a Supabase mock.
10		 *
11		 * Design: docs/plans/2026-07-09-spending-report-design.md
12		 */
13	
14		import type { HierarchyTree } from '$lib/utils/hierarchyTree';
15		import type { ImportanceArea } from '$lib/types/Hierarchy';
16	
17		interface Props {
18			tree: HierarchyTree;
19			importanceAreas: ImportanceArea[];
20			saving?: boolean;
21			/** groupId is null when the category is set back to Uncategorized. */
22			onAssignCategory: (categoryId: string, groupId: string | null) => void;
23			onMoveGroup: (groupId: string, importanceAreaId: string) => void;
24			onCreateGroup: (name: string, importanceAreaId: string) => void;
25			onRenameGroup: (groupId: string, name: string) => void;
26		}
27	
28		let {
29			tree,
30			importanceAreas,
31			saving = false,
32			onAssignCategory,
33			onMoveGroup,
34			onCreateGroup,
35			onRenameGroup
