1	import { vi, type Mock } from 'vitest';
2	import type { SupabaseClient } from '@supabase/supabase-js';
3	
4	/**
5	 * Shared chainable Supabase client mock for DI-style service specs.
6	 *
7	 * The services under test (`ExpenseService`, `CategoryService`, and any other
8	 * constructor-injected service) take a `SupabaseClient` and issue PostgREST-style
9	 * chains — `from(table).select(...).eq(...).single()` / `.upsert(...)` / a bare
10	 * `await from(table)...`. This builder returns a single shared query stub per client
11	 * where every filter/modifier method returns `this`, so the chain is order-agnostic
12	 * and a test only has to set `data` / `error` (or override a terminal like `single`)
13	 * for the path it exercises.
14	 *
15	 * This is the one canonical builder — do NOT hand-roll another `createMockSupabaseClient`
16	 * in a spec. It is a superset of the two shapes that previously diverged
17	 * (`ExpenseService`'s and `CategoryService`'s), so both suites consume it unchanged.
18	 *
19	 * NOT for the `ReceiptService.*` / reconciliation specs: those `vi.mock('$lib/supabaseClient')`
20	 * and wire explicit per-call chains that return *different* results across a sequence
21	 * (fetch original → insert split → update → delete). A single shared `mockReturnThis`
22	 * stub can't express that, and `vi.mock` is hoisted per-module so its preamble can't be
23	 * import-shared anyway. Leave those as-is.
24	 */
25	export interface MockQueryBuilder {
26		data: unknown;
27		error: { message: string; code?: string } | null;
28		select: Mock;
29		eq: Mock;
30		gte: Mock;
31		lte: Mock;
32		ilike: Mock;
33		in: Mock;
34		order: Mock;
35		range: Mock;
36		returns: Mock;
37		insert: Mock;
38		update: Mock;
39		delete: Mock;
40		upsert: Mock;
41		single: Mock;
42		then: Mock;
43	}
44	
45	/** Retrieve the query stub behind `client.from(table)` with its mock surface exposed. */
46	export function getMockQuery(client: SupabaseClient, table: string): MockQueryBuilder {
47		return client.from(table) as unknown as MockQueryBuilder;
48	}
49	
50	/** Replace what the mocked `client.from()` returns for subsequent calls. */
51	export function setFromResult(client: SupabaseClient, builder: object): void {
52		(client.from as unknown as Mock).mockReturnValue(builder);
53	}
54	
55	/**
56	 * Build a chainable Supabase client mock with a single shared query stub.
57	 *
58	 * `single()` and the thenable `then()` both read the stub's live `data` / `error`
59	 * (so a test sets `getMockQuery(client, table).data = …` once); `single()` also unwraps
60	 * a non-empty array to its first element, mirroring PostgREST's single-row semantics.
61	 */
62	export function createMockSupabaseClient(): SupabaseClient {
63		const mockQuery = {
64			data: null as unknown,
65			error: null as { message: string; code?: string } | null,
66			select: vi.fn().mockReturnThis(),
67			eq: vi.fn().mockReturnThis(),
68			gte: vi.fn().mockReturnThis(),
69			lte: vi.fn().mockReturnThis(),
70			ilike: vi.fn().mockReturnThis(),
71			in: vi.fn().mockReturnThis(),
72			order: vi.fn().mockReturnThis(),
73			range: vi.fn().mockReturnThis(),
74			returns: vi.fn().mockReturnThis(),
75			insert: vi.fn().mockReturnThis(),
76			update: vi.fn().mockReturnThis(),
77			delete: vi.fn().mockReturnThis(),
78			upsert: vi.fn().mockResolvedValue({ data: null, error: null }),
79			single: vi.fn(function (this: MockQueryBuilder) {
80				// PostgREST single-row: unwrap a non-empty array to its first element.
81				if (Array.isArray(this.data) && this.data.length > 0) {
82					return Promise.resolve({ data: this.data[0], error: this.error });
83				}
84				return Promise.resolve({ data: this.data, error: this.error });
85			}),
86			then: vi.fn(function (this: MockQueryBuilder, resolve: (value: unknown) => unknown) {
87				// Make the query object awaitable for `const { data, error } = await from()...`.
88				return resolve({ data: this.data, error: this.error });
89			})
90		};
91	
92		return {
93			from: vi.fn().mockReturnValue(mockQuery),
94			rpc: vi.fn().mockResolvedValue({ data: null, error: null }),
95			auth: {
96				getUser: vi.fn().mockResolvedValue({ data: { user: { id: 'test-user-id' } }, error: null }),
97				getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user-id' } } } })
98			}
99		} as unknown as SupabaseClient;
100	}
